// 官網卡圖 URL (プロモ新規カードは官網に画像が無いので空)
function getCardImageUrl(id)
{
	var base = "https://ange-unite.com/_assets_/hjangeunite/";
	if(id == "omega" || id == "sigma") return base + "cardlist01/large/" + id + ".png";
	var m = id.match(/^(\d)-\d{3}(F?)$/);
	if(!m) return "";
	return base + "cardlist0" + m[1] + "/large/" + id + (m[2] ? "_foil" : "") + ".png";
}

for(var _i = 0; _i < cardData.length; _i++)
{
	cardData[_i][SRC] = getCardImageUrl(cardData[_i][ID]);
}
